CREATE TABLE IF NOT EXISTS gis_phase39117_data_plane_audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_version text NOT NULL, schema_name text NOT NULL, schema_status text NOT NULL, migration_status text NOT NULL, postgis_status text NOT NULL, gis_tables_discovered jsonb NOT NULL DEFAULT '[]'::jsonb, geometry_columns jsonb NOT NULL DEFAULT '[]'::jsonb, data_counts jsonb NOT NULL DEFAULT '{}'::jsonb, provenance_classifications jsonb NOT NULL DEFAULT '{}'::jsonb, migration_discrepancies jsonb NOT NULL DEFAULT '[]'::jsonb, recoverable_sources jsonb NOT NULL DEFAULT '[]'::jsonb, blocked_sources jsonb NOT NULL DEFAULT '[]'::jsonb, candidate_mutation_count integer NOT NULL DEFAULT 0, production_gate text NOT NULL, blocking_errors jsonb NOT NULL DEFAULT '[]'::jsonb, fingerprint text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS gis_phase39117_audit_created_idx ON gis_phase39117_data_plane_audits(created_at DESC);